<script setup>
import {reactive,ref,watch} from 'vue'
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app'
import VehicleList from '../../components/VehicleList.vue'
import QuestionConfirmation from '../../components/QuestionConfirmation.vue'
import {ownerSession} from '../../services/owner-session.js'
import {selectedOwnerVehicle,selectOwnerVehicle} from '../../services/owner-vehicle-selection.js'
import {createKnowledgeApi,knowledgeRoute,knowledgeReference} from '../../services/licensed-knowledge.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {createQuestionConfirmation} from '../../services/community-question-recovery.js'
const vehicle=selectedOwnerVehicle,api=createKnowledgeApi(),routeValid=ref(true),mode=ref('search'),reference=ref(''),query=ref(''),question=ref(''),submitted=ref(''),cursor=ref(null),state=reactive(initialDiagnosisState()),confirmation=reactive({prompt:null}),prompt=ref(null)
const allowed=()=>routeValid.value&&Boolean(vehicle.value?.model_id)
const gate=createQuestionConfirmation({state:confirmation,preview:()=>prompt.value})
const flow=createAsyncDiagnosisFlow({state,token:()=>ownerSession.accessToken,allowed,scope:()=>`${ownerSession.actorId}:${vehicle.value?.vehicle_id}:${vehicle.value?.model_id}:${mode.value}:${reference.value}:${submitted.value}:${cursor.value}`,load:t=>mode.value==='detail'?api.detail(t,vehicle.value.vehicle_id,vehicle.value.model_id,reference.value):mode.value==='answer'?api.answer(t,vehicle.value.vehicle_id,vehicle.value.model_id,submitted.value):api.search(t,vehicle.value.vehicle_id,vehicle.value.model_id,submitted.value,cursor.value)})
let visible=false,epoch=0
function clear(){epoch++;gate.cancel();flow.reset()}
function search(){if(state.busy)return;clear();mode.value='search';reference.value='';submitted.value=query.value.trim();cursor.value=null;if(submitted.value)flow.load();else state.message='请输入资料关键词'}
function detail(id){if(state.busy||!knowledgeReference(id))return;clear();mode.value='detail';reference.value=id;if(visible)flow.load()}
async function answer(){if(state.busy||!allowed()||!ownerSession.accessToken)return;const value=question.value.trim();if(!value){state.message='请输入本次资料问题';return}const current=++epoch,t=ownerSession.accessToken,v=vehicle.value?.vehicle_id,m=vehicle.value?.model_id;prompt.value={title:'确认发送问题并参考许可资料',lines:[value,'只发送本次文字及服务器重新核验且允许AI使用的专业资料摘录，不读取或发送私有车辆档案。','AI仅供参考，可能出错；来源会再次核验，缺来源时不生成有来源回答。']};if(!await gate.ask('answer')||!visible||current!==epoch||t!==ownerSession.accessToken||v!==vehicle.value?.vehicle_id||m!==vehicle.value?.model_id)return;flow.reset();mode.value='answer';reference.value='';submitted.value=value;cursor.value=null;await flow.load()}
function next(){if(state.busy||mode.value!=='search'||!state.data?.next_cursor)return;cursor.value=state.data.next_cursor;flow.load()}
function copy(id){if(!state.busy&&ownerSession.accessToken&&allowed()&&knowledgeReference(id))uni.setClipboardData({data:knowledgeReference(id)})}
function start(){if(!visible||!ownerSession.accessToken||!allowed())return;if(mode.value==='detail'||submitted.value)flow.load()}
watch(()=>[ownerSession.accessToken,ownerSession.actorId,vehicle.value?.vehicle_id,vehicle.value?.model_id],()=>{clear();question.value='';query.value='';submitted.value='';cursor.value=null;start()},{flush:'sync'})
onLoad(q=>{const r=knowledgeRoute(q||{});routeValid.value=Boolean(r);reference.value=r?.reference||'';mode.value=reference.value?'detail':'search'})
onShow(()=>{visible=true;start()});function hide(){visible=false;clear();question.value='';query.value='';submitted.value='';cursor.value=null}onHide(hide);onUnload(hide)
</script>
<template><view class="reservation-page"><text class="reservation-title">有来源专业资料</text><text>按本人车型、资料许可和有效期核验；当前使用关键词检索，不代表向量相似度。未配置或证据不足显示未知。</text><text v-if="!routeValid">资料引用入口无效</text><button v-if="!ownerSession.accessToken" @tap="uni.navigateTo({url:'/pages/owner/index'})">车主登录</button><VehicleList :selected-id="vehicle?.vehicle_id||0" @select="selectOwnerVehicle"/><input v-model="query" maxlength="80" :disabled="state.busy" placeholder="请输入部件或症状关键词"/><button :disabled="state.busy||!allowed()" @tap="search">核验并检索资料</button><textarea v-model="question" maxlength="2000" :disabled="state.busy" placeholder="可选：本次资料问题，最多1000字，请勿填写私有标识"/><button :disabled="state.busy||!allowed()" @tap="answer">确认用途后生成AI参考</button><text v-if="state.busy">正在核验资料来源…</text><text v-if="state.message" role="status">{{state.message}}</text><template v-if="state.data"><text v-if="state.data.state&&state.data.state!=='AVAILABLE'">{{state.data.state==='UNAVAILABLE'?'资料库尚未启用':'暂无可核验的匹配资料，状态未知；可尝试更具体关键词'}}</text><text v-if="submitted">本次查询：{{submitted}}</text><view v-for="row in state.data.items||[]" :key="row.reference" class="reservation-panel"><text>{{row.title}} · {{row.document_version}}</text><text>{{row.publisher}} · 有效至 {{row.valid_to}}</text><text class="knowledge-text">{{row.excerpt}}</text><text class="knowledge-text">来源：{{row.source_reference}}</text><button :disabled="state.busy" @tap="detail(row.reference)">重新核验资料引用</button></view><view v-if="state.data.document" class="reservation-panel"><text>{{state.data.document.title}} · {{state.data.document.document_version}}</text><text>出版者 {{state.data.document.publisher}} · 有效至 {{state.data.document.valid_to}}</text><text class="knowledge-text">许可摘录：{{state.data.document.body}}</text><text class="knowledge-text">来源：{{state.data.document.source_reference}}</text><button :disabled="state.busy" @tap="copy(state.data.document.reference)">复制可追溯应用内引用</button></view><view v-if="state.data.reply" class="reservation-panel"><text>AI参考，不能替代到店检查</text><text class="knowledge-text">{{state.data.reply}}</text><text>实际提供给AI的当前许可资料：</text><view v-for="row in state.data.provided_sources" :key="row.reference"><text>{{row.title}} · {{row.document_version}} · {{row.source_reference}}</text><button :disabled="state.busy" @tap="detail(row.reference)">独立核验此资料</button></view></view><button v-if="state.data.next_cursor" :disabled="state.busy" @tap="next">继续核验后续资料</button></template><QuestionConfirmation :prompt="confirmation.prompt" @answer="gate.settle"/></view></template>
<style scoped>.knowledge-text{white-space:pre-wrap;overflow-wrap:anywhere}</style>
